/// Look up a model identifier in [`MODELS`] by short key (for example `"GPT_5_4_MINI"`).
pub fn model_id(key: &str) -> Option<&'static str> {
    MODELS
        .binary_search_by_key(&key, |(k, _)| *k)
        .ok()
        .map(|idx| MODELS[idx].1)
}
